// generated by rtl_gen.py; neurons=128 fanout=8 ww=4 seed=1
// weights live in external SRAM (OpenSpike interface): fabric has none
`timescale 1ns/1ps
module snn_core_128 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        timestep_start,
    input  wire [128-1:0] in_spk,
    input  wire [512-1:0] w_read_sram,
    output reg  [8-1:0] w_read_sram_addr,
    output reg         spike_out_valid,
    output reg  [15:0] spike_out_addr,
    output reg         spike_out_data
);
localparam N = 128;
localparam PAD = 128;
localparam AW = 8;
localparam WW = 4;
localparam ACC_W = 16;
localparam signed ACC_W_THR = 16'sd16;
localparam signed ACC_W_REST = 16'sd0;
localparam signed ACC_W_LEAK = 16'sd0;
localparam signed DECAY_NUM = 14;
localparam DECAY_SHIFT = 4;
localparam PH_IDLE = 0, PH_RUN = 1,
          PH_UPDATE = 2, PH_EMIT = 3;

reg [1:0] phase;
reg signed [ACC_W-1:0] v [0:PAD-1];
reg signed [ACC_W-1:0] acc [0:PAD-1];
reg [PAD-1:0] fire_shift;
reg [PAD-1:0] in_spk_buf;
reg [8:0] scnt;  // counts PAD too, one extra bit

// decayed membrane, 32-bit intermediate, no truncation before compare
wire signed [31:0] decayed [0:PAD-1];
genvar gi;
generate
    for (gi = 0; gi < PAD; gi = gi + 1) begin : g_decay
        assign decayed[gi] = (v[gi] * DECAY_NUM) >>> DECAY_SHIFT;
    end
endgenerate

// sign-extended weight word straight off the SRAM bus, one word per cycle
wire signed [ACC_W-1:0] col_part [0:PAD-1];
generate
    for (gi = 0; gi < PAD; gi = gi + 1) begin : g_acc
        assign col_part[gi] = $signed({ { (ACC_W-WW){ w_read_sram[gi*WW + WW-1] } }, w_read_sram[gi*WW +: WW] });
    end
endgenerate
// word currently on the bus + its input spike gate
wire [AW-1:0] s_word = scnt - 1'b1;
wire spk_gate = (scnt != 0) && in_spk_buf[s_word];

reg [PAD-1:0] fires;
reg [PAD-1:0] emit_tmp;
reg found;
reg signed [31:0] v_cand;
integer i;
always @(posedge clk) begin
    if (!rst_n) begin
        phase <= PH_IDLE;
        fire_shift <= {PAD{1'b0}};
        w_read_sram_addr <= {AW{1'b0}};
        scnt <= {(AW+1){1'b0}};
        for (i = 0; i < PAD; i = i + 1) begin
            v[i] <= ACC_W_REST;
            acc[i] <= {ACC_W{1'b0}};
        end
        spike_out_valid <= 1'b0;
        spike_out_addr <= 16'd0;
        spike_out_data <= 1'b0;
    end else begin
        spike_out_valid <= 1'b0;
        case (phase)
            PH_IDLE: begin
                if (timestep_start) begin
                    in_spk_buf <= in_spk;
                    w_read_sram_addr <= {AW{1'b0}};
                    scnt <= {(AW+1){1'b0}};
                    phase <= PH_RUN;
                end
            end
            PH_RUN: begin
                // word (scnt-1) is on the bus this cycle (addr in N, data in N+1)
                for (i = 0; i < PAD; i = i + 1)
                    acc[i] <= acc[i] + (spk_gate ? col_part[i] : {ACC_W{1'b0}});
                if (scnt + 1 < PAD)
                    w_read_sram_addr <= scnt + 1'b1;
                scnt <= scnt + 1'b1;
                if (scnt == PAD) phase <= PH_UPDATE;  // last word (PAD-1) consumed
            end
            PH_UPDATE: begin
                fires = {PAD{1'b0}};
                for (i = 0; i < PAD; i = i + 1) begin
                    v_cand = decayed[i] + acc[i] - ACC_W_LEAK;
                    if (v_cand >= ACC_W_THR) begin
                        fires[i] = 1'b1;
                        v[i] <= ACC_W_REST;
                    end else begin
                        v[i] <= v_cand[ACC_W-1:0];
                    end
                    acc[i] <= {ACC_W{1'b0}};
                end
                fire_shift <= fires;
                phase <= PH_EMIT;
            end
            PH_EMIT: begin
                emit_tmp = fire_shift;
                found = 1'b0;
                for (i = 0; i < PAD; i = i + 1) begin
                    if (!found && emit_tmp[i]) begin
                        found = 1'b1;
                        spike_out_addr <= i;
                        spike_out_data <= 1'b1;
                        spike_out_valid <= 1'b1;
                        emit_tmp[i] = 1'b0;
                    end
                end
                fire_shift <= emit_tmp;
                if (emit_tmp == {PAD{1'b0}}) phase <= PH_IDLE;
            end
        endcase
    end
end
endmodule
